import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

/**
 * Unit tests for TimeSeries.createCopy(int, int).
 */
public class TimeSeries_createCopy_TriageGen1Test {

    private TimeSeries series;
    private RegularTimePeriod period1;
    private RegularTimePeriod period2;
    private RegularTimePeriod period3;

    @Before
    public void setUp() {
        series = new TimeSeries("Test Series");

        // Create dummy periods using MillisecondRegularTimePeriod via a simple construction if possible,
        // but since we don't have the specific implementation, we'll use a mock-like approach or standard JFreeChart periods.
        // For the sake of this test, we assume standard JFreeChart components are available.
        period1 = new org.jfree.data.time.SecondRegularTimePeriod(new java.util.Date(1000));
        period2 = new org.jfree.data.time.SecondRegularTimePeriod(new java.util.Date(2000));
        period3 = new org.jfree.data.time.SecondRegularTimePeriod(new java.util.Date(3000));

        series.add(period1, 10.0);
        series.add(period2, 20.0);
        series.add(period3, 30.0);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreateCopyStartLessThanZero() throws CloneNotSupportedException {
        series.createCopy(-1, 1);
    }

    @Test(expected = IllegalArgumentException.class)
    public void testCreateCopyEndLessThanStart() throws CloneNotSupportedException {
        series.createCopy(1, 0);
    }

    @Test
    public void testCreateCopyFullRange() throws CloneNotSupportedException {
        TimeSeries copy = series.createCopy(0, 2);

        assertNotNull(copy);
        assertEquals(series.getItemCount(), copy.getItemCount());
        assertEquals(series.getDomainDescription(), copy.getDomainDescription());
        assertEquals(series.getRangeDescription(), copy.getRangeDescription());

        // Check values
        for (int i = 0; i < series.getItemCount(); i++) {
            assertEquals(series.getValue(i), copy.getValue(i));
            assertEquals(series.getTimePeriod(i), copy.getTimePeriod(i));
        }

        // Verify that it's a deep copy of items (different object references)
        for (int i = 0; i < series.getItemCount(); i++) {
            assertTrue(series.getDataItem(i) != copy.getDataItem(i));
        }

        // Check that min/max Y were reset to NaN as per implementation
        assertTrue(Double.isNaN(copy.getMinY()));
        assertTrue(Double.isNaN(copy.getMaxY()));
    }

    @Test
    public void testCreateCopyPartialRange() throws CloneNotSupportedException {
        // Copy only the middle element (index 1)
        TimeSeries copy = series.createCopy(1, 1);

        assertEquals(1, copy.getItemCount());
        assertEquals(series.getValue(1), copy.getValue(0));
        assertEquals(series.getTimePeriod(1), copy.getTimePeriod(0));

        assertTrue(Double.isNaN(copy.getMinY()));
        assertTrue(Double.isNaN(copy.getMaxY()));
    }

    @Test
    public void testCreateCopyEmptyRange() throws CloneNotSupportedException {
        // Start == End is a valid range containing one element in the loop (index <= end)
        // However, if we want to test the logic when start == end:
        TimeSeries copy = series.createCopy(0, 0);
        assertEquals(1, copy.getItemCount());
    }

    @Test
    public void testCreateCopyWithEmptySeries() throws CloneNotSupportedException {
        TimeSeries emptySeries = new TimeSeries("Empty");
        // The implementation checks if (this.data.size() >= 0), which is always true for an ArrayList.
        // However, if the loop range is invalid for the size, it would throw IndexOutOfBounds.
        // Given the logic, if start=0, end=0 on an empty series, it will throw IndexOutOfBoundsException.
        try {
            emptySeries.createCopy(0, 0);
        } catch (IndexOutOfBoundsException e) {
            // Expected behavior based on the provided source code's loop logic
        }
    }

    @Test
    public void testCreateCopyDeepCopyVerification() throws CloneNotSupportedException {
        TimeSeries copy = series.createCopy(0, 2);

        // Modify original
        series.update(0, 99.0);

        // Copy should remain unchanged
        assertEquals(10.0, copy.getValue(0).doubleValue(), 0.001);
        assertNotEquals(series.getValue(0).doubleValue(), copy.getValue(0).doubleValue(), 0.001);
    }
}
